package com.nextaicommerce.platform.shopify;
import com.nextaicommerce.platform.marketplace.ShopifySkuRepository;import com.nextaicommerce.platform.web.ShopifyConnectionService;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.assertj.core.api.Assertions.*;
class ShopifyCatalogWorkerTest {
 final ShopifyCatalogJobs jobs=mock(ShopifyCatalogJobs.class);final ShopifyCatalogClient client=mock(ShopifyCatalogClient.class);final ShopifySkuRepository skus=mock(ShopifySkuRepository.class);final ShopifyCatalogWorker worker=new ShopifyCatalogWorker(jobs,client,skus);
 final UUID tenant=new UUID(0,1),connection=new UUID(0,2),id=new UUID(0,3),run=new UUID(0,4);final Instant revision=Instant.parse("2026-10-26T12:00:00Z");final ShopifyCatalogJobs.Job job=new ShopifyCatalogJobs.Job(tenant,connection,id,run,"owner",1,Map.of("connectionRevision",revision.toString()));
 @Test void disabledWorkerCannotReadOrWrite(){worker.start(tenant,connection,id);verifyNoInteractions(client,skus);verify(jobs,never()).claim(any(),any(),any());}
 @Test void publicationAndMatchingAreInsideLiveJobFence(){var response=new ShopifyConnectionService.CatalogResponse("raw","gid://shopify/Shop/1","USD",revision);var page=new ShopifyCatalogClient.Page(List.of(),"end",false,10,1000,100);when(client.fetch(eq(tenant),eq(connection),isNull(),any())).thenAnswer(i->{((Runnable)i.getArgument(3)).run();return response;});when(client.parse(response,null)).thenReturn(page);doAnswer(i->{((Runnable)i.getArgument(4)).run();return null;}).when(jobs).publish(eq(job),eq("raw"),eq(page),eq("USD"),any());assertThat(worker.process(job)).isFalse();verify(jobs).reserve(job);verify(skus).autoMap(tenant,connection,run);}
 @Test void changedConnectionRevisionAndLostLeaseCannotPublish(){when(client.fetch(eq(tenant),eq(connection),isNull(),any())).thenReturn(new ShopifyConnectionService.CatalogResponse("raw","shop","USD",Instant.EPOCH));assertThat(worker.process(job)).isFalse();verify(jobs,never()).publish(any(),any(),any(),any(),any());verifyNoInteractions(skus);}
 @Test void permissionRevocationOnlyTerminatesItsFencedMetadata(){when(client.fetch(eq(tenant),eq(connection),isNull(),any())).thenThrow(new org.springframework.security.access.AccessDeniedException("revoked"));assertThat(worker.process(job)).isFalse();verify(jobs).pauseRevoked(job);verifyNoInteractions(skus);}
 @Test void malformedPageArchivesFailureWithoutMapping(){var response=new ShopifyConnectionService.CatalogResponse("raw","shop","USD",revision);when(client.fetch(eq(tenant),eq(connection),isNull(),any())).thenReturn(response);when(client.parse(response,null)).thenThrow(new IllegalArgumentException("Incomplete page"));assertThat(worker.process(job)).isFalse();verify(jobs).fail(job,"raw","Incomplete page");verifyNoInteractions(skus);}
 @Test void temporaryTransportFailureSchedulesBoundedRetry(){when(client.fetch(eq(tenant),eq(connection),isNull(),any())).thenThrow(new IllegalStateException("unavailable"));assertThat(worker.process(job)).isTrue();verify(jobs).retry(eq(job),any(Instant.class));verifyNoInteractions(skus);}
}
